//! Boot artwork for JuanitOS, drawn procedurally.
//!
//! Three programs show the same picture at different moments of a boot,
//! and the transitions must be seamless:
//!
//! 1. `jos-boot` (UEFI pre-loader) paints it on the GOP framebuffer before
//!    chain-loading FreeBSD's `loader.efi`;
//! 2. the kernel's `vt(4)` draws a PNG of it, generated by `jos-release`
//!    with this crate, while the kernel boots muted;
//! 3. `jos-splash` (an early rc daemon) redraws it on the framebuffer and
//!    lights the stage icons up, BeOS/Haiku style, until the desktop takes
//!    over.
//!
//! Hence everything is here: colours, the logo, the icons, the bitmap font
//! and the layout of the "card" that is centred on the screen. No image
//! assets, no decoder, no allocator surprises: `no_std` + `alloc`, pure
//! integer/float math, unit-tested on any host.

#![no_std]
#![forbid(unsafe_code)]

extern crate alloc;
#[cfg(any(feature = "png", test))]
extern crate std;

pub mod color;
pub mod font;
pub mod icons;
pub mod image;
#[cfg(feature = "png")]
pub mod png;
pub mod scene;

pub use color::Rgba;
pub use image::Image;
pub use scene::{Scene, Stage, CARD_HEIGHT, CARD_WIDTH, STAGES};
